\begin{tikzpicture}[
                pantalla/.style={draw=BrandBlue, very thick, rounded corners},
                bloque/.style={draw=PracticeTitle, fill=PracticeBody, thick,
                    rounded corners=2pt}
                ]
                \draw[pantalla] (0,0) rectangle (6.7,3.6);
                \node[font=\bfseries] at (3.35,3.95) {Pantalla amplia};
                \draw[bloque] (0.35,2.65) rectangle (6.35,3.25);
                \draw[bloque] (0.35,0.45) rectangle (2.1,2.35);
                \draw[bloque] (2.35,0.45) rectangle (6.35,2.35);

                \draw[pantalla] (8.5,0) rectangle (10.7,3.6);
                \node[font=\bfseries] at (9.6,3.95) {Pantalla estrecha};
                \draw[bloque] (8.8,2.65) rectangle (14.8,3.25);
                \draw[bloque] (8.8,0.45) rectangle (10.55,2.35);
                \draw[bloque] (10.8,0.45) rectangle (14.8,2.35);
                \draw[->, very thick, WarnTitle] (10.9,1.3) -- (12.1,1.3)
                node[right] {desbordamiento};
            \end{tikzpicture}

\begin{tikzpicture}[
                base/.style={draw=BrandBlue, thick, rounded corners,
                    minimum width=3.2cm, minimum height=1.2cm, align=center}
                ]
                \node[base, fill=IdeaBody] at (1.8,2) {Distribución\\flexible};
                \node[base, fill=PracticeBody] at (6,2) {Imágenes y medios\\adaptables};
                \node[base, fill=ResultBody] at (10.2,2) {Reglas según\\el espacio};
                \draw[->, >=Latex, thick] (3.45,2) -- (4.35,2);
                \draw[->, >=Latex, thick] (7.65,2) -- (8.55,2);
            \end{tikzpicture}

\begin{tikzpicture}[
                marco/.style={draw=BrandBlue, very thick, rounded corners=8pt},
                pagina/.style={draw=PracticeTitle, thick, fill=PracticeBody}
                ]
                \draw[marco] (0,0) rectangle (4.2,5.4);
                \draw[pagina] (0.35,0.55) rectangle (3.85,4.85);
                \node at (2.1,4.45) {contenido visible};
                \draw[<->, >=Latex, thick] (0.35,0.25) -- (3.85,0.25)
               node[midway, below=5mm] {ancho del viewport};

                \node[align=left, text width=6.1cm] at (8.2,3.2) {
                    El \textit{viewport} es la región del navegador donde
                    se representa la página.\\[0.4cm]
                    CSS toma decisiones a partir de ese espacio disponible,
                    no del tamaño físico total del dispositivo.
                };
            \end{tikzpicture}

\begin{tikzpicture}[
                foto/.style={draw=BrandBlue, thick, fill=IdeaBody},
                flecha/.style={->, >=Latex, thick}
                ]
                \draw[foto] (0,0.6) rectangle (4,3.1);
                \node at (2,1.85) {imagen original};
                \draw[flecha] (4.4,1.85) -- (5.5,1.85);
                \draw[foto] (5.9,1.05) rectangle (9.1,3.05);
                \node at (7.5,2.05) {proporción};
                \draw[flecha, WarnTitle] (9.5,1.85) -- (10.6,1.85);
                \draw[draw=WarnTitle, thick, fill=WarnBody]
                (11,0.3) rectangle (12.8,3.4);
                \node[rotate=90] at (11.9,1.85) {deformada};
            \end{tikzpicture}

\begin{tikzpicture}[
    marco/.style={
        draw=BrandBlue,
        very thick,
        fill=gray!5
    },
    imagen/.style={
        draw=PracticeTitle,
        thick,
        fill=PracticeBody
    }
    ]





    \node[font=\bfseries] at (2.6,3.7) {cover};


    \draw[imagen]
    (0,0.7) rectangle (5.2,3.2);


    \draw[
    PracticeTitle,
    thick,
    dashed
    ]
    (-0.65,0.7) rectangle (5.85,3.2);


    \draw[marco, fill=none]
    (0,0.7) rectangle (5.2,3.2);

    \node[align=center] at (2.6,1.95)
    {cubre todo el espacio\\y recorta los extremos};

    \node[
    font=\scriptsize,
    text=WarnTitle
    ] at (2.6,0.3)
    {parte de la imagen queda fuera};





   \begin{scope}[xshift=0.5cm]

       \node[font=\bfseries] at (8.5,3.7) {contain};


       \draw[marco]
       (5.9,0.7) rectangle (11.1,3.2);


       \draw[imagen]
       (6.7,0.7) rectangle (10.3,3.2);

       \node[align=center] at (8.5,1.95)
       {muestra toda la imagen\\
           y deja espacio libre};

   \end{scope}

\end{tikzpicture}

\begin{tikzpicture}[x=0.012cm]
                \draw[very thick, ->, >=Latex] (320,0) -- (1200,0);
                \foreach \x/\t in {360/360,700/700,1000/1000}{
                    \draw[thick] (\x,-0.18) -- (\x,0.18);
                    \node[below] at (\x,-0.22) {\t px};
                }
                \draw[very thick, PracticeTitle] (700,0.45) -- (1180,0.45);
                \node[above, PracticeTitle] at (940,0.45)
                {se aplican las reglas de \texttt{min-width: 700px}};
            \end{tikzpicture}

\begin{tikzpicture}[
                regla/.style={draw=BrandBlue, thick, rounded corners,
                    minimum width=3.6cm, minimum height=0.85cm}
                ]
                \node[regla, fill=IdeaBody] (base) at (2.2,2.4) {regla base};
                \node[regla, fill=PracticeBody] (media) at (8.2,2.4) {regla en media query};
                \draw[->, >=Latex, very thick] (4.1,2.4) -- (6.0,2.4)
                node[midway, above] {después};
                \node[align=center] at (4.7,0.9)
                {si la condición se cumple,\\la segunda puede sobrescribir la primera};
            \end{tikzpicture}

\begin{tikzpicture}[
               node distance=0.8cm,
               etapa/.style={
                   draw=BrandBlue,
                   thick,
                   rounded corners,
                   text width=3.2cm,
                   minimum height=1.1cm,
                   inner sep=4pt,
                   align=center,
                   font=\small
               },
               flecha/.style={
                   ->,
                   >=Latex,
                   very thick
               }
               ]

               \node[
               etapa,
               fill=IdeaBody
               ] (m) {
                   Reglas base\\
                   una columna
               };

               \node[
               etapa,
               fill=PracticeBody,
               right=of m
               ] (t) {
                   \texttt{min-width: 700px}\\
                   dos columnas
               };

               \node[
               etapa,
               fill=ResultBody,
               right=of t
               ] (d) {
                   \texttt{min-width: 1000px}\\
                   composición amplia
               };

               \draw[flecha] (m) -- (t);
               \draw[flecha] (t) -- (d);

           \end{tikzpicture}

\begin{tikzpicture}[
                bloque/.style={draw=PracticeTitle, thick, fill=PracticeBody,
                    minimum height=1.3cm}
                ]
                \node[bloque, minimum width=5cm] at (3.2,1.2) {imagen};
                \node[bloque, minimum width=4cm] at (8,1.2) {texto};
            \end{tikzpicture}

\begin{tikzpicture}[
                scale=0.8,
                transform shape,
                marco/.style={draw=BrandBlue, very thick, rounded corners=5pt},
                bloque/.style={draw=PracticeTitle, fill=PracticeBody, thick,
                    rounded corners=2pt}
                ]
                \node[font=\bfseries] at (2,5.4) {Vista estrecha};
                \draw[marco] (0,0) rectangle (4,5);
                \draw[bloque] (0.3,4.2) rectangle (3.7,4.7);
                \draw[bloque] (0.3,3.35) rectangle (3.7,3.95);
                \draw[bloque] (0.3,2.05) rectangle (3.7,3.1);
                \draw[bloque] (0.3,1.1) rectangle (3.7,1.8);
                \draw[bloque] (0.3,0.25) rectangle (3.7,0.95);

                \node[font=\bfseries] at (9.4,5.4) {Vista amplia};
                \draw[marco] (5.1,0) rectangle (13.7,5);
                \draw[bloque] (5.4,4.2) rectangle (13.4,4.7);
                \draw[bloque] (5.4,3.5) rectangle (13.4,4);
                \draw[bloque] (5.4,1.9) rectangle (10,3.25);
                \draw[bloque] (10.2,1.9) rectangle (13.4,3.25);
                \draw[bloque] (5.4,0.35) rectangle (9.2,1.6);
                \draw[bloque] (9.6,0.35) rectangle (13.4,1.6);
            \end{tikzpicture}

\begin{tikzpicture}[
                scale=0.88,
                transform shape,
                nodo/.style={draw=BrandBlue, thick, rounded corners,
                    minimum width=3.4cm, minimum height=0.85cm, align=center},
                flecha/.style={->, >=Latex, thick}
                ]
                \node[nodo, fill=IdeaBody] (p) at (5.5,5.3) {¿El contenido se desborda?};
                \node[nodo, fill=PracticeBody] (f) at (2.2,2.6) {Use medidas flexibles\\e imágenes adaptables};
                \node[nodo, fill=PracticeBody] (c) at (8.8,2.6) {¿La composición deja\\de ser clara?};
                \node[nodo, fill=ResultBody] (m) at (8.8,0.8) {Agregue una media query};
                \draw[flecha] (p) -- (f) node[midway, above left] {sí};
                \draw[flecha] (p) -- (c) node[midway, above right] {no};
                \draw[flecha] (c) -- (m) node[midway, right] {sí};
            \end{tikzpicture}
